begin;
create function pg_temp.track(t text) returns jsonb language sql security definer set search_path='' as $$select public.production_tracking(t)$$;
create function pg_temp.legacy(p_order uuid) returns void language sql security definer set search_path='' as $$update private.production_tracking set recoverable_token=null,last_request_id=null where order_id=p_order$$;
select set_config('request.jwt.claim.sub',(select id::text from public.profiles where active and personnel_category='ceo' limit 1),true);
set local role authenticated;
do $$
declare creator uuid:=auth.uid();manager uuid;unit uuid;fleet uuid;driver uuid;truck uuid;cust uuid;site uuid;prod uuid;ord uuid;lid uuid;lid2 uuid;token text;newtoken text;key uuid:=gen_random_uuid();departure_key uuid:=gen_random_uuid();bad boolean;response jsonb;
begin
 select id into strict manager from public.profiles where email='concrete@ruelconcreteltd.com' and active;
 select id into strict unit from public.business_units where code='CONC-PR';select id into strict fleet from public.business_units where code='MOBILE-PR';
 select p.id into strict driver from public.profiles p join public.user_unit_access a on a.user_id=p.id where p.active and p.full_name like '[MOC]%' and a.business_unit_id=fleet limit 1;
 perform public.production_command('driver',jsonb_build_object('business_unit_id',fleet,'user_id',driver));
 select id into strict truck from public.assets where business_unit_id=fleet and status='active' limit 1;
 cust:=(public.production_command('customer',jsonb_build_object('business_unit_id',unit,'name','[QA rollback] Tracking customer'))->>'id')::uuid;
 site:=(public.production_command('site',jsonb_build_object('business_unit_id',unit,'customer_id',cust,'name','QA site','address','QA no real dispatch'))->>'id')::uuid;
 prod:=(public.production_command('product',jsonb_build_object('business_unit_id',unit,'name','QA mix','unit','m³','kind','product'))->>'id')::uuid;
 ord:=(public.production_command('order',jsonb_build_object('business_unit_id',unit,'customer_id',cust,'site_id',site,'product_id',prod,'quantity',14,'due_at',now()+interval '1 day','request_id',gen_random_uuid()))->>'id')::uuid;
 response:=public.production_tracking_link(ord,creator,'read',gen_random_uuid());if response ? 'token' then raise exception 'Read created a tracking link';end if;
 token:=public.production_tracking_link(ord,creator,'ensure',key)->>'token';
 if length(token)<>48 or public.production_tracking_link(ord,creator,'ensure',gen_random_uuid())->>'token'<>token then raise exception 'Repeated copy rotated link';end if;
 perform set_config('request.jwt.claim.sub',manager::text,true);
 if public.production_tracking_link(ord,manager,'read',gen_random_uuid())->>'token'<>token then raise exception 'Other authorized manager cannot retrieve same link';end if;
 bad:=false;begin perform public.production_tracking_link(ord,creator,'ensure',gen_random_uuid());exception when raise_exception then bad:=true;end;if not bad then raise exception 'Forged link actor accepted';end if;
 perform pg_temp.legacy(ord);
 if not (public.production_tracking_link(ord,manager,'ensure',gen_random_uuid())->>'legacy')::boolean or pg_temp.track(token) is null then raise exception 'Legacy hash-only link was silently invalidated';end if;
 key:=gen_random_uuid();newtoken:=public.production_tracking_link(ord,manager,'replace',key)->>'token';
 if newtoken=token or pg_temp.track(token) is not null or pg_temp.track(newtoken) is null or public.production_tracking_link(ord,manager,'replace',key)->>'token'<>newtoken then raise exception 'Explicit replacement or retry failed';end if;
 lid:=(public.production_command('schedule',jsonb_build_object('order_id',ord,'fleet_unit_id',fleet,'driver_id',driver,'truck_id',truck,'quantity',7))->>'id')::uuid;
 lid2:=(public.production_command('schedule',jsonb_build_object('order_id',ord,'fleet_unit_id',fleet,'driver_id',driver,'truck_id',truck,'quantity',7))->>'id')::uuid;
 bad:=false;begin perform public.production_command('dispatch',jsonb_build_object('load_id',lid,'client_id',departure_key));exception when raise_exception then bad:=true;end;if not bad then raise exception 'Unproduced load dispatched';end if;
 perform public.production_command('produce',jsonb_build_object('load_id',lid));perform public.production_command('produce',jsonb_build_object('load_id',lid2));
 perform set_config('request.jwt.claim.sub',driver::text,true);
 bad:=false;begin perform public.production_command('dispatch',jsonb_build_object('load_id',lid,'client_id',departure_key));exception when raise_exception then bad:=true;end;if not bad then raise exception 'Driver used dispatcher action';end if;
 bad:=false;begin perform public.production_tracking_link(ord,driver,'read',gen_random_uuid());exception when raise_exception then bad:=true;end;if not bad then raise exception 'Driver retrieves private tracking token';end if;
 perform set_config('request.jwt.claim.sub',manager::text,true);
 perform public.production_command('dispatch',jsonb_build_object('load_id',lid,'actor_id',manager,'client_id',departure_key));
 perform public.production_command('dispatch',jsonb_build_object('load_id',lid,'actor_id',manager,'client_id',departure_key));
 if (select count(*) from public.production_activity where order_id=ord and kind='departed')<>1 or (select status from public.production_loads where id=lid)<>'departed' then raise exception 'Departure retry duplicated event';end if;
 perform set_config('request.jwt.claim.sub',creator::text,true);
 if not exists(select 1 from public.notifications where user_id=creator and production_order_id=ord and message='Dispatcher confirmed departure from plant') then raise exception 'Order creator did not receive departure notification';end if;
 perform set_config('request.jwt.claim.sub',manager::text,true);
 if pg_temp.track(newtoken)->>'status'<>'partially dispatched' then raise exception 'Partial dispatch tracking status incorrect';end if;
 bad:=false;begin perform public.production_command('dispatch',jsonb_build_object('load_id',lid2,'client_id',gen_random_uuid()));exception when raise_exception then bad:=true;end;if not bad then raise exception 'Dispatcher bypassed occupied driver/truck';end if;
 perform set_config('request.jwt.claim.sub',driver::text,true);
 perform public.production_command('event',jsonb_build_object('load_id',lid,'event','departed','client_id',gen_random_uuid()));
 perform public.production_command('event',jsonb_build_object('load_id',lid,'event','arrived','client_id',gen_random_uuid()));
 perform public.production_command('event',jsonb_build_object('load_id',lid,'event','completed','client_id',gen_random_uuid()));
 perform set_config('request.jwt.claim.sub',manager::text,true);
 perform public.production_command('dispatch',jsonb_build_object('load_id',lid2,'client_id',gen_random_uuid()));
 if pg_temp.track(newtoken)->>'status'<>'dispatched' or (select status from public.production_orders where id=ord)<>'confirmed' then raise exception 'Actual dispatch status or open workflow changed incorrectly';end if;
 if exists(select 1 from public.production_receipts where load_id in (lid,lid2)) then raise exception 'Departure invented customer acceptance';end if;
end $$;
set local role anon;
do $$begin if has_function_privilege('anon','public.production_tracking_link(uuid,uuid,text,uuid)','execute') then raise exception 'Anonymous link-retrieval access';end if;end$$;
reset role;
select 'dispatch_departure_tracking_passed' as result;
rollback;
